<?php
declare(strict_types=1);mysqli_report(MYSQLI_REPORT_ERROR|MYSQLI_REPORT_STRICT);
$db=getenv('DB_NAME')?:'';if(!str_ends_with($db,'_test')&&!str_contains($db,'dev'))exit("Refusing to seed non-development/test database.\n");
$conn=new mysqli(getenv('DB_HOST')?:'127.0.0.1',getenv('DB_USER')?:'root',getenv('DB_PASS')?:'',$db,(int)(getenv('DB_PORT')?:3307));$conn->set_charset('utf8mb4');
$fixtures=[['ANON-FAM-001','yapayao','Test Tribe','Poblacion','Upper Test','Dalisay','Amihan','Female','Dalisay','Luntian','Male'],['ANON-FAM-002','kankanaey','Test Tribe','Adams','Lower Test','Masikhay','Tala',null,null,null,null],['ANON-FAM-003','isneg','Test Tribe','Adams',null,'Mapayapa','Sinag','Other','Mapayapa','Bituin',null]];
$conn->begin_transaction();try{foreach($fixtures as[$ref,$code,$owner,$barangay,$sitio,$last,$first,$sex,$slast,$sfirst,$ssex]){$aff=(int)$conn->query("SELECT id FROM ip_affiliations WHERE code='".$conn->real_escape_string($code)."'")->fetch_row()[0];$stmt=$conn->prepare("INSERT INTO ip_families(family_reference,affiliation_id,owning_tribe,province,municipality_city,barangay,sitio_street,id_type) VALUES (?,? ,?,'Fictional Province','Development Municipality',?,?, 'Sample ID') ON DUPLICATE KEY UPDATE family_reference=VALUES(family_reference)");$stmt->bind_param('sisss',$ref,$aff,$owner,$barangay,$sitio);$stmt->execute();$fid=(int)$conn->query("SELECT id FROM ip_families WHERE family_reference='".$conn->real_escape_string($ref)."'")->fetch_row()[0];$stmt=$conn->prepare("INSERT INTO ip_family_members(family_id,member_role,last_name,first_name,sex) VALUES (?,'head',?,?,?) ON DUPLICATE KEY UPDATE last_name=VALUES(last_name),first_name=VALUES(first_name),sex=VALUES(sex)");$stmt->bind_param('isss',$fid,$last,$first,$sex);$stmt->execute();if($slast){$stmt=$conn->prepare("INSERT INTO ip_family_members(family_id,member_role,last_name,first_name,sex) VALUES (?,'spouse',?,?,?) ON DUPLICATE KEY UPDATE last_name=VALUES(last_name),first_name=VALUES(first_name),sex=VALUES(sex)");$stmt->bind_param('isss',$fid,$slast,$sfirst,$ssex);$stmt->execute();}}$conn->commit();echo "Anonymized family fixtures seeded safely.\n";}catch(Throwable $e){$conn->rollback();throw$e;}
